from abc import ABC
from typing import List
from bs4 import BeautifulSoup
import re
from datetime import datetime
from crawler.crawler_instance.local_interface_model.leak.leak_extractor_interface import leak_extractor_interface
from crawler.crawler_instance.local_shared_model.data_model.entity_model import entity_model
from crawler.crawler_instance.local_shared_model.data_model.leak_model import leak_model
from crawler.crawler_instance.local_shared_model.rule_model import RuleModel, FetchProxy, FetchConfig, ThreatType
from crawler.crawler_services.redis_manager.redis_controller import redis_controller
from crawler.crawler_services.shared.helper_method import helper_method


class _csocybercrime(leak_extractor_interface, ABC):
    _instance = None

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super(_csocybercrime, cls).__new__(cls)
            cls._instance._initialized = False
        return cls._instance

    def __init__(self, callback=None):
        if self._initialized:
            return
        self.callback = callback
        self._card_data = []
        self._entity_data = []
        self._redis_instance = redis_controller()
        self._is_crawled = False
        self._initialized = True

    def init_callback(self, callback=None):
        self.callback = callback

    @property
    def seed_url(self) -> str:
        return "https://www.csoonline.com/news"

    @property
    def base_url(self) -> str:
        return "https://www.csoonline.com"

    @property
    def developer_signature(self) -> str:
        return "Muhammad Hannan Zahid:"

    @property
    def rule_config(self) -> RuleModel:
        return RuleModel(m_fetch_proxy=FetchProxy.NONE,m_fetch_config=FetchConfig.REQUESTS,m_resoource_block=False,m_threat_type=ThreatType.NEWS)

    @property
    def card_data(self) -> List:
        return self._card_data

    @property
    def is_crawled(self) -> bool:
        return self._is_crawled

    @property
    def entity_data(self) -> List:
        return self._entity_data

    def invoke_db(self, command: int, key: str, default_value, expiry: int = None):
        return self._redis_instance.invoke_trigger(
            command, [key + self.__class__.__name__, default_value, expiry]
        )

    def contact_page(self) -> str:
        return "https://www.csoonline.com/contact-us/"

    def append_leak_data(self, leak: leak_model, entity: entity_model):
        self._card_data.append(leak)
        self._entity_data.append(entity)
        if self.callback and self.callback():
            self._card_data.clear()
            self._entity_data.clear()

    def parse_leak_data(self, page):
        html = page._seed_response.text
        soup = BeautifulSoup(html, "html.parser")

        links = []

        cards = soup.select(
            'div.latest-content__content-featured a.card, div.latest-content__content-main .card, div.latest-content__content-secondary .card')

        for card in cards:
            href = card.get('href')
            date_el = card.select_one('[itemprop="datePublished"]') or card.select_one('.card__info--light span')

            dt = datetime.strptime(date_el.text.strip(), "%b %d, %Y")
            links.append((href, dt.date()))

        for link, date in links:
            html1 = page.get(link, timeout=30).text
            soup1 = BeautifulSoup(html1, "html.parser")

            title_el = soup1.select_one('h1.article-hero__title')
            title = title_el.get_text(strip=True)

            imp_el = soup1.select_one('.content-subheadline')
            first_content = imp_el.get_text(strip=True)

            body_text_parts = []
            body_container = soup1.select_one('#remove_no_follow')

            if body_container:
                for element in body_container.select('p, h2, h3, li'):
                    text = element.get_text(strip=True)
                    if text:
                        body_text_parts.append(text)

            body_text_str = "".join(body_text_parts)
            main_content = f"{first_content}{body_text_str}"
            m_content = re.sub(r'\s+', ' ', main_content).strip()
            imp_content = main_content[:500]

            card_data = leak_model(
                m_title=title,
                m_url=link,
                m_base_url=self.base_url,
                m_content=m_content,
                m_network=helper_method.get_network_type(self.base_url),
                m_important_content=imp_content,
                m_weblink=[link],
                m_content_type=["news"],
                m_leak_date = date,
            )

            entity_data = entity_model()

            self.append_leak_data(card_data, entity_data)
